task max_occurrences(s: seq) returns (r: int)
  requires len(s) > 0
  ensures forall i in [0, len(s)) . r >= count(s, i)
  ensures exists i in [0, len(s)) . r == count(s, i)
{
  r := s[0];
  var max_count: int := 1;
  var i: int := 1;
  while i < len(s)
    invariant 1 <= i and i <= len(s)
    invariant forall j in [0, i) . max_count >= count(s, j)
    invariant exists j in [0, i) . max_count == count(s, j)
    decreases len(s) - i
  {
    var count_i: int := count(s, s[i]);
    if count_i > max_count {
      max_count := count_i;
      r := s[i];
    }
    i := i + 1;
  }
}
